// === Tab: mySketch ===
let num = 100;
let pos = [];
let vel = [];

let framesDown = 0;

function setup() {
	createCanvas(1920, 1026);
	colorMode(RGB)
	strokeWeight(2);
	textAlign(LEFT, TOP);
	resetParticles();
}

function draw() {
	background(0);
	noStroke();
	fill(255);
	text(round(frameRate()), 10, 10);
	text(num, 10, 25);

	//automatically deleting or adding particles to have the most particles while still getting around 50fps
	//not totally accurate but gets it done pretty well
	if (frameCount % 20 == 0) {
		if (frameRate() > 55) {
			for(let i = 0; i < 10; i++) {
				pos[num+i] = createVector(width/2, height/2);
				vel[num+i] = createVector(0, 0);
			}
			num += 0;
		} else if (frameRate() > 50) {
			num -= 0;
		}
	}

	for(let i = 0; i < num; i++) {
		pos[i].add(vel[i]);
		pos[i].x = (pos[i].x + width) % width;
		pos[i].y = (pos[i].y + height) % height;
		vel[i].add(createVector(random(-1, 1), random(-1, 1)).mult(0));
		vel[i].mult(1);
		stroke((frameCount*3+i/num*255)%360, 127, 255);
		line(pos[i].x, pos[i].y, pos[i].x - vel[i].x * 5, pos[i].y - vel[i].y * 5);
		// circle(pos[i].x, pos[i].y, 5);

		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
			let baseAttraction = sqrt(framesDown)/25
			let attraction = baseAttraction / pow(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), pos[i].x, pos[i].y), -1);
			let attractionVector = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - pos[i].x, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - pos[i].y).setMag(attraction);
			vel[i].add(attractionVector);
		}
	}

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		framesDown++;
	} else {
		framesDown = 0;
	}
}

function resetParticles() {
	background(0);
	pos = [];
	vel = [];
	for(let i = 0; i < num; i++) {
		pos[i] = createVector(width/2, height/2);
		vel[i] = createVector(random(-1, 1), random(-1, 1));
	}
}

